∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] {K : Foundations.Algebra.Subfield Ω} {α : Ω}
  (hΩ : Foundations.Algebra.IsField Ω) (C : Foundations.Algebra.CubicRoot K α),
  K.le (Foundations.Algebra.CubicRoot.field hΩ C)

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] {K : Foundations.Algebra.Subfield Ω}
  (S : Foundations.Algebra.KSubspace K) {ι : Type v} [inst_1 : Foundations.Algebra.FiniteType ι]
  (f : ι → { x // S.carrier x }), (Foundations.Algebra.isum f).val = Foundations.Algebra.isum fun i => (f i).val

∀ {G : Type u} [inst : Foundations.Algebra.Group G] [inst_1 : Foundations.Algebra.FiniteType G] {A : Type}
  [inst_2 : Foundations.Algebra.AddAbGroup A] (h : G) (F : G → A),
  (Foundations.Algebra.isum fun g => F (h * g * h⁻¹)) = Foundations.Algebra.isum F

∀ {G : Type u} [inst : Foundations.Algebra.Group G] [inst_1 : Foundations.Algebra.FiniteType G] {A : Type}
  [inst_2 : Foundations.Algebra.AddAbGroup A] (y : G) (F : G → A),
  (Foundations.Algebra.isum fun x => F (x * y)) = Foundations.Algebra.isum F

∀ {K : Type w} [inst : Foundations.Algebra.CommRing K] {ι : Type v} [Foundations.Algebra.FiniteType ι] {α : Type u}
  [inst_2 : Foundations.Algebra.FiniteType α] (v : Foundations.Langlands.Vec ι K),
  (Foundations.Algebra.isum fun x => v) = Foundations.Algebra.ncast (Foundations.Algebra.FiniteType.card α) • v

∀ {G : Type u} [inst : Foundations.Algebra.Group G] [inst_1 : Foundations.Algebra.FiniteType G] {A : Type w}
  [inst_2 : Foundations.Algebra.AddAbGroup A] (h : G) (F : G → A),
  (Foundations.Algebra.isum fun g => F (h * g)) = Foundations.Algebra.isum F

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] {K : Foundations.Algebra.Subfield Ω} {α : Ω}
  (hΩ : Foundations.Algebra.IsField Ω) (C : Foundations.Algebra.CubicRoot K α) {F : Foundations.Algebra.Subfield Ω},
  K.le F → α ∈ F → (Foundations.Algebra.CubicRoot.field hΩ C).le F

{p : Nat} →
  Foundations.Numbers.Arith.Prime p →
    (Nat → Foundations.Langlands.Padic.Zp p) → Nat → { S // Foundations.Combinatorics.InfOften S }

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] (hΩ : Foundations.Algebra.IsField Ω)
  (hc : Foundations.Algebra.CharZero Ω) {α : Ω}
  (C : Foundations.Algebra.CubicRoot (Foundations.Algebra.ratField hΩ hc) α), ¬Foundations.Algebra.Constructible hΩ hc α

∀ {G : Type u} [inst : Foundations.Algebra.CommGroup G] [Foundations.Algebra.FiniteType G] {K : Type w}
  [inst_2 : Foundations.Algebra.CommRing K] (χ : G → K) (h1 : χ 1 = 1) (hmul : ∀ (g h : G), χ (g * h) = χ g * χ h),
  Foundations.Langlands.character (Foundations.Langlands.Rep.ofHom χ h1 hmul) = χ

∀ {G : Type u} [inst : Foundations.Algebra.Group G] [inst_1 : Foundations.Algebra.FiniteType G] {K : Type w}
  [inst_2 : Foundations.Algebra.CommRing K] (c : K) (χ ψ : G → K),
  Foundations.Langlands.pairing (fun g => c * χ g) ψ = c * Foundations.Langlands.pairing χ ψ

∀ {G : Type u} [inst : Foundations.Algebra.CommGroup G] [Foundations.Algebra.FiniteType G] {K : Type w}
  [inst_2 : Foundations.Algebra.CommRing K],
  Foundations.Algebra.IsField K → ∀ (ρ : Foundations.Langlands.Rep G K Unit), Foundations.Langlands.Irreducible ρ

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y E : C} {f g : Foundations.Categories.Category.Hom X Y}
  {e : Foundations.Categories.Category.Hom E X} (hE : Foundations.Categories.IsEqualizer f g E e) {W : C}
  {h k : Foundations.Categories.Category.Hom W E},
  Foundations.Categories.Category.comp h e = Foundations.Categories.Category.comp k e → h = k

∀ {G : Type u} [inst : Foundations.Algebra.Group G] {K : Type w} [inst_1 : Foundations.Algebra.CommRing K] {ι : Type v}
  [inst_2 : Foundations.Algebra.FiniteType ι] (ρ : Foundations.Langlands.Rep G K ι) (x : Foundations.Langlands.Vec ι K),
  (ρ.toFun 1).mulVec x = x

∀ {G : Type u} [inst : Foundations.Algebra.Group G] {N : Foundations.Algebra.Subgroup G}
  {P : Foundations.Algebra.QuotientGroup N → Prop},
  (∀ (a : G), P (Foundations.Algebra.QuotientGroup.mk N a)) → ∀ (q : Foundations.Algebra.QuotientGroup N), P q

∀ {X Y : Foundations.Bridges.ZFCat}
  (f : Foundations.Categories.Category.Hom (Foundations.Bridges.El.obj X) (Foundations.Bridges.El.obj Y)),
  ∃ F, Foundations.Bridges.El.map F = f

∀ {G : Type u} [inst : Foundations.Algebra.CommGroup G] [Foundations.Algebra.FiniteType G] {ι : Type v}
  [inst_2 : Foundations.Algebra.FiniteType ι] {ρ : Foundations.Langlands.Rep G Foundations.Numbers.C ι},
  Foundations.Langlands.Irreducible ρ → Foundations.NumberTheory.IsChar (Foundations.Langlands.character ρ)
